/* Real Java/Android-core browser acceptance. The ready file is generated by DesktopServer.
 * Usage: node scripts/web-live.cjs [ready.json]; requires optional playwright package.
 * Credentials are read in memory and never printed or copied into source or screenshots.
 */
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const engines=require('playwright'),engine=process.env.FILEFLASH_BROWSER_ENGINE||'chromium';
const ready=JSON.parse(fs.readFileSync(process.argv[2]||path.resolve(__dirname,'../.test-data/browser-ready.json'),'utf8'));
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
const source=crypto.randomBytes(4*1024*1024+173),name='网页实测 中文 & café '+Date.now()+'.bin';
const longText='浏览器 → Android\n中文 English 😀 特殊符号 <script>no execution</script> & "\n'+'较长多行文字🙂\n'.repeat(1000);
(async()=>{
  const browser=await engines[engine].launch(engine==='chromium'?{headless:true,channel:process.env.FILEFLASH_BROWSER_CHANNEL||'chromium'}:{headless:true});
  const context=await browser.newContext({viewport:{width:375,height:812},reducedMotion:'reduce',acceptDownloads:true});
  const page=await context.newPage(),pageErrors=[];page.on('pageerror',e=>pageErrors.push(e.message));
  let injected=false,confirmedFirst=false,blockNetwork=true;
  await page.route('**/api/uploads/*',async route=>{
    const request=route.request();
    if(request.method()==='PUT'&&Number(request.headers()['x-offset'])>0&&blockNetwork){injected=true;await route.abort('connectionfailed');return;}
    if(request.method()==='PUT'&&request.headers()['x-offset']==='0')confirmedFirst=true;
    await route.continue();
  });
  try{
    await page.goto(ready.url+'/#pair='+encodeURIComponent(ready.pairToken));await page.locator('#connection-label').filter({hasText:'已连接'}).waitFor();assert.equal(new URL(page.url()).hash,'');
    await page.locator('#file-input').setInputFiles({name,mimeType:'application/octet-stream',buffer:source});
    await page.locator('.task-error').filter({hasText:'连接中断。恢复网络后可重试'}).waitFor({timeout:30000});assert.ok(injected&&confirmedFirst);
    let task=await page.evaluate(()=>JSON.parse(localStorage.getItem('fileflash.tasks.v1')).find(t=>t.name.startsWith('网页实测')));assert.equal(task.offset,2097152);const uploadId=task.id;
    blockNetwork=false;await page.reload();await page.locator('#connection-label').filter({hasText:'已连接'}).waitFor();await page.locator('[data-tab="tasks"]').click();
    const wrong=Buffer.from(source);wrong[0]^=1;await page.getByRole('button',{name:'选择原文件',exact:true}).click();await page.locator('#file-input').setInputFiles({name,mimeType:'application/octet-stream',buffer:wrong});
    await page.getByText('所选文件与原文件内容不同。请重新选择原文件。',{exact:true}).waitFor();
    await page.getByRole('button',{name:'选择原文件',exact:true}).click();await page.locator('#file-input').setInputFiles({name,mimeType:'application/octet-stream',buffer:source});
    await page.locator('.task-state').filter({hasText:'已完成'}).waitFor({timeout:30000});
    task=await page.evaluate(()=>JSON.parse(localStorage.getItem('fileflash.tasks.v1')).find(t=>t.name.startsWith('网页实测')));assert.equal(task.id,uploadId);assert.equal(task.offset,source.length);assert.equal(task.sha256,hash(source));
    await page.locator('[data-tab="files"]').click();const row=page.locator('.file-row').filter({hasText:name});await row.waitFor();
    const downloadEvent=page.waitForEvent('download');await row.getByRole('button',{name:'下载',exact:true}).click();const download=await downloadEvent;assert.equal(hash(await fs.promises.readFile(await download.path())),hash(source));
    await page.locator('[data-tab="texts"]').click();await page.locator('#text-input').fill(longText);await page.getByRole('button',{name:'发送',exact:true}).click();
    await page.waitForFunction(value=>Array.from(document.querySelectorAll('.received-text')).some(el=>el.value===value),longText);assert.equal(await page.locator('script').count(),2);
    await page.locator('.text-card').first().getByRole('button',{name:'复制',exact:true}).click();await page.locator('.copy-note').filter({hasText:/已复制|已选中文字/}).first().waitFor();
    // Empty files and batch serialization must also finish through the real completion checksum.
    await page.locator('[data-tab="files"]').click();await page.locator('#choose-files').click();await page.locator('#file-input').setInputFiles([{name:'空文件-'+Date.now()+'.bin',mimeType:'application/octet-stream',buffer:Buffer.alloc(0)},{name:'批次-'+Date.now()+'.txt',mimeType:'text/plain',buffer:Buffer.from('多文件队列')}]);
    await page.waitForFunction(()=>JSON.parse(localStorage.getItem('fileflash.tasks.v1')).filter(t=>t.status==='complete').length===3);
    assert.equal(await page.locator('.task-state').filter({hasText:'失败'}).count(),0);
    for(const viewport of [{width:375,height:812},{width:812,height:375},{width:768,height:1024},{width:1440,height:900}]){await page.setViewportSize(viewport);assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'layout overflow');}
    await page.setViewportSize({width:375,height:812});const out=path.resolve(__dirname,'web-artifacts',engine);await fs.promises.mkdir(out,{recursive:true});await page.screenshot({path:path.join(out,'live-core-tasks.png'),fullPage:true});await page.locator('[data-tab="files"]').click();await page.screenshot({path:path.join(out,'live-core-files.png'),fullPage:true});
    await page.locator('#connection-button').click();await page.getByRole('button',{name:'断开连接',exact:true}).click();await page.locator('#pair-panel').waitFor();assert.equal(await page.evaluate(()=>JSON.parse(localStorage.getItem('fileflash.session.v1'))),null);
    assert.deepEqual(pageErrors,[]);console.log('PASS ('+engine+') against real Java core: pairing, secret removal, 4MiB+173 bytes, network interruption after 2MiB, reload, wrong reselect rejected, same-ID recovery, final SHA, native browser download byte equality, long Unicode text, copy fallback, 0-byte and batch uploads, 4 viewport widths, session revoke.');
    console.log('Desktop browser engine only; this is not a physical iOS Safari/Android device test.');
  }catch(error){console.error('Browser state:',(await page.locator('body').innerText()).slice(0,3000));console.error('Page errors:',pageErrors);throw error;}finally{await browser.close();}
})().catch(e=>{console.error(e);process.exitCode=1;});
